void cmd_trace( Cmd cmd  )
{  
#if DBG_CMD == 1

  TRACE_CMD("[CMD_%04d]",(cmd & (INPUT_ON - 1)) );
  
  if( cmd & INPUT_ON         ) TRACE_CMD("--ON\n\r" );
  else
  if( cmd & INPUT_RF_EXT     ) TRACE_CMD("--EXT\n\r" );
  else
  if( cmd & INPUT_RF_RELEASE ) TRACE_CMD("--RELEASE\n\r" );
  else
  TRACE_CMD("\n\r" );
#endif
}

